setattr(SeriesIndicators, '_get_data_', _get_data_)  # noqa
setattr(AnalysisIndicators, '_finta_get_data', _finta_get_data)  # noqa
setattr(SeriesIndicators, '_finta_get_data', _finta_get_data)  # noqa
