    def pta_rs_sma(self, length: int = 10, **kwargs):
        """简单移动平均（SMA）（pandas_ta 的 Rust 版）

        SMA = alpha.MA(close, length)

        参数：length: int = 10
        """
        from .ta_ import _LazyModule

        alpha = _LazyModule("alpha")
        rs = _pta_rs_arrays(self)
        index = rs["index"]
        close = rs.get("close")
        high = rs.get("high")
        low = rs.get("low")
        volume = rs.get("volume")
        return pd.Series(alpha.MA(close, length), index=index)

