        index = rs["index"]
        close = rs.get("close")
        high = rs.get("high")
        low = rs.get("low")
        volume = rs.get("volume")
        median = (high + low) / 2.0
        return pd.Series(alpha.MA(median, fast) - alpha.MA(median, slow),
                         index=index)

